import{_ as e,o,c as r,ag as a}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/docs-editor/format-text-more-fonts.png",s="/docs/images/docs-editor/format-text-styles-options.png",m=JSON.parse('{"title":"Format text","description":"Style text in a doc with bold, fonts, colors, headings, alignment, line spacing, and links.","frontmatter":{"title":"Format text","description":"Style text in a doc with bold, fonts, colors, headings, alignment, line spacing, and links.","type":"how-to"},"headers":[],"relativePath":"docs-editor/format-text.md","filePath":"docs-editor/format-text.md"}'),i={name:"docs-editor/format-text.md"};function l(d,t,h,c,g,p){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="format-text" tabindex="-1">Format text <a class="header-anchor" href="#format-text" aria-label="Permalink to &quot;Format text&quot;">​</a></h1><p>Style the words in a doc, set paragraph styles such as headings, and add links. Formatting changes apply to the selected text, or to what you type next if nothing is selected.</p><h2 id="make-text-bold-italic-or-underlined" tabindex="-1">Make text bold, italic, or underlined <a class="header-anchor" href="#make-text-bold-italic-or-underlined" aria-label="Permalink to &quot;Make text bold, italic, or underlined&quot;">​</a></h2><ol><li>Select the text.</li><li>Click <strong>Bold</strong>, <strong>Italic</strong>, or <strong>Underline</strong> in the toolbar, or press <code>⌘+B</code> / <code>Ctrl+B</code>, <code>⌘+I</code> / <code>Ctrl+I</code>, or <code>⌘+U</code> / <code>Ctrl+U</code>.</li></ol><p>Click the button again to turn the style off.</p><h3 id="strikethrough-superscript-and-subscript" tabindex="-1">Strikethrough, superscript, and subscript <a class="header-anchor" href="#strikethrough-superscript-and-subscript" aria-label="Permalink to &quot;Strikethrough, superscript, and subscript&quot;">​</a></h3><p>These have no toolbar button. Select the text and press:</p><ul><li>Strikethrough: <code>⌘+Shift+X</code> / <code>Ctrl+Shift+X</code></li><li>Superscript: <code>⌘+.</code> / <code>Ctrl+.</code></li><li>Subscript: <code>⌘+,</code> / <code>Ctrl+,</code></li></ul><h2 id="change-the-font-and-size" tabindex="-1">Change the font and size <a class="header-anchor" href="#change-the-font-and-size" aria-label="Permalink to &quot;Change the font and size&quot;">​</a></h2><ol><li>Select the text.</li><li>Open the <strong>Font</strong> dropdown (it shows <strong>Arial</strong> in a new document) and select a font. Fonts you used recently are listed first under <strong>Recent</strong>.</li><li>To find another font, select <strong>More fonts…</strong>, search or filter the list, and select one.</li><li>In <strong>Font size</strong>, type a number and press <code>Enter</code>, or click <strong>−</strong> and <strong>+</strong>.</li></ol><p>Sizes range from 1 to 400. A new document uses Arial 11.</p><p><img src="'+n+'" alt="Fonts dialog with a search box and a filtered list of font families"></p><h2 id="change-text-and-highlight-color" tabindex="-1">Change text and highlight color <a class="header-anchor" href="#change-text-and-highlight-color" aria-label="Permalink to &quot;Change text and highlight color&quot;">​</a></h2><ol><li>Select the text.</li><li>Click <strong>Text color</strong> or <strong>Highlight color</strong> (marker icon) in the toolbar. Each button shows its current color.</li><li>Click a swatch.</li></ol><p>To remove a color, open the same palette and click <strong>Reset</strong> (text color) or <strong>None</strong> (highlight).</p><h2 id="copy-formatting-with-format-painter" tabindex="-1">Copy formatting with Format painter <a class="header-anchor" href="#copy-formatting-with-format-painter" aria-label="Permalink to &quot;Copy formatting with Format painter&quot;">​</a></h2><ol><li>Put the cursor in text that has the formatting you want.</li><li>Click <strong>Format painter</strong> (brush icon) next to undo and redo. The button stays lit.</li><li>Select the text to restyle, then click <strong>Format painter</strong> again.</li></ol><p>The selection takes on the copied formatting, and the button turns off. To cancel without applying, click the lit button with nothing selected.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To paint several places in a row, use the keyboard: press <code>⌘+Shift+C</code> / <code>Ctrl+Shift+C</code> to copy the formatting, then select each target and press <code>⌘+Option+V</code> / <code>Ctrl+Alt+V</code>.</p></div><h2 id="clear-formatting" tabindex="-1">Clear formatting <a class="header-anchor" href="#clear-formatting" aria-label="Permalink to &quot;Clear formatting&quot;">​</a></h2><ol><li>Select the text.</li><li>Click <strong>Clear formatting</strong> in the toolbar, or press <code>⌘+\\</code> / <code>Ctrl+\\</code>.</li></ol><p>Bold, italic, underline, strikethrough, fonts, sizes, and colors are removed. Links stay.</p><h2 id="apply-a-heading-or-paragraph-style" tabindex="-1">Apply a heading or paragraph style <a class="header-anchor" href="#apply-a-heading-or-paragraph-style" aria-label="Permalink to &quot;Apply a heading or paragraph style&quot;">​</a></h2><ol><li>Put the cursor in the paragraph.</li><li>Open the <strong>Styles</strong> dropdown at the left of the toolbar and select a style: <strong>Normal text</strong>, <strong>Title</strong>, <strong>Subtitle</strong>, or <strong>Heading 1</strong> to <strong>Heading 6</strong>.</li></ol><p>You can also type <code>#</code> to <code>######</code> and press <code>Space</code> at the start of an empty line to get Heading 1 to Heading 6, or press <code>⌘+Option+1</code> to <code>⌘+Option+6</code> / <code>Ctrl+Alt+1</code> to <code>Ctrl+Alt+6</code>. Pressing the shortcut for the heading a line already has turns it back into normal text.</p><h2 id="redefine-a-style-for-this-document" tabindex="-1">Redefine a style for this document <a class="header-anchor" href="#redefine-a-style-for-this-document" aria-label="Permalink to &quot;Redefine a style for this document&quot;">​</a></h2><ol><li>Format some text the way you want a style to look, for example a Heading 2 in a new color and font.</li><li>With the cursor in that text, open <strong>Styles</strong> and select <strong>Options</strong>.</li><li>Select <strong>Update &#39;Heading 2&#39; to match</strong>. The menu names whichever style the cursor is in.</li></ol><p>Every paragraph that uses the style updates. In the same <strong>Options</strong> menu:</p><ul><li><strong>Reset &#39;Heading 2&#39;</strong> puts that style back to its built-in look.</li><li><strong>Reset styles</strong> puts every style back.</li></ul><p><img src="'+s+'" alt="Styles dropdown open with the Options submenu showing Update to match and Reset items"></p><h3 id="reuse-your-styles-in-other-documents" tabindex="-1">Reuse your styles in other documents <a class="header-anchor" href="#reuse-your-styles-in-other-documents" aria-label="Permalink to &quot;Reuse your styles in other documents&quot;">​</a></h3><ol><li>In a document whose styles you like, open <strong>Styles &gt; Options</strong> and select <strong>Save as my default styles</strong>.</li><li>In another document, open <strong>Styles &gt; Options</strong> and select <strong>Use my default styles</strong>.</li></ol><p>The saved styles belong to your account, so only you can apply them.</p><h2 id="align-paragraphs" tabindex="-1">Align paragraphs <a class="header-anchor" href="#align-paragraphs" aria-label="Permalink to &quot;Align paragraphs&quot;">​</a></h2><ol><li>Put the cursor in the paragraph, or select several.</li><li>Open <strong>Text alignment</strong> in the toolbar and select <strong>Left</strong>, <strong>Center</strong>, <strong>Right</strong>, or <strong>Justify</strong>.</li></ol><p>The shortcuts are listed in the menu, for example <code>⌘+Shift+E</code> / <code>Ctrl+Shift+E</code> to center.</p><h2 id="set-line-spacing" tabindex="-1">Set line spacing <a class="header-anchor" href="#set-line-spacing" aria-label="Permalink to &quot;Set line spacing&quot;">​</a></h2><ol><li>Put the cursor in the paragraph, or select several.</li><li>Open <strong>Line spacing</strong> in the toolbar and select <strong>1.0</strong>, <strong>1.15</strong>, <strong>1.5</strong>, or <strong>2.0</strong>.</li><li>For another value, select <strong>Custom…</strong>, type a number from 0.5 to 10, and press <code>Enter</code>.</li></ol><h2 id="add-a-link" tabindex="-1">Add a link <a class="header-anchor" href="#add-a-link" aria-label="Permalink to &quot;Add a link&quot;">​</a></h2><ol><li>Select the text to link.</li><li>Press <code>⌘+K</code> / <code>Ctrl+K</code>, click <strong>Insert link</strong> in the toolbar, or right-click and select <strong>Add link</strong>.</li><li>Type the address and click <strong>Apply</strong>, or press <code>Enter</code>.</li></ol><p>If you skip <code>https://</code>, it is added for you. With nothing selected, the address itself is inserted as linked text.</p><p>A web address that starts with <code>http://</code> or <code>https://</code> also becomes a link when you type a space or press <code>Enter</code> after it.</p><h3 id="edit-open-or-remove-a-link" tabindex="-1">Edit, open, or remove a link <a class="header-anchor" href="#edit-open-or-remove-a-link" aria-label="Permalink to &quot;Edit, open, or remove a link&quot;">​</a></h3><ol><li>Click inside the link. A small box shows its address.</li><li>Click the address to open it in a new tab, click <strong>Edit link</strong> (pencil) to change it, or click <strong>Remove link</strong> to keep the text but drop the link.</li></ol><p>People with view-only access see the address but not the edit and remove buttons.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>The toolbar shows undo, redo, <strong>Format painter</strong>, <strong>Bold</strong>, <strong>Italic</strong>, <strong>Underline</strong>, both colors, and <strong>Clear formatting</strong>. Tap ⋮ (<strong>More formatting options</strong>) at the right end of the toolbar for:</p><ul><li><strong>Font</strong>: the font and size pickers</li><li><strong>Styles</strong>: Normal text, Title, Subtitle, and headings (redefining styles needs a computer)</li><li><strong>Insert &gt; Link</strong></li><li><strong>Align</strong> and <strong>Spacing</strong> (line spacing)</li></ul><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Strikethrough, superscript, and subscript need a keyboard; there is no toolbar button.</li><li>Paragraph spacing before and after a paragraph can&#39;t be set; use line spacing instead.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/lists-and-indents.html">Lists and indents</a> to build bulleted and numbered lists.</li><li><a href="/docs/docs-editor/paste-from-other-apps.html">Paste from other apps</a> to see which formatting survives a paste.</li><li><a href="/docs/docs-editor/keyboard-shortcuts.html">Keyboard shortcuts</a> for every formatting shortcut.</li><li><a href="/docs/start/troubleshooting.html#the-cursor-left-this-link-click-it-again-to-edit-it">Troubleshooting</a> if a link says &quot;The cursor left this link&quot;.</li></ul>',52)])])}const f=e(i,[["render",l]]);export{m as __pageData,f as default};
